// encodeHTTPGenericResponse is a transport/http.EncodeResponseFunc that encodes
// the response as JSON to the response writer. Primarily useful in a server.
func encodeHTTPGenericResponse(ctx context.Context, cfg *nhttp.Config, w http.ResponseWriter, response interface{}) error {
	if writer, ok := response.(nhttp.ResponseWriter); ok {
		return writer.WriteHttpResponse(ctx, w)
	}

	if isNilResponse(response) {
		response = nil
	}
	if _, ok := response.(*core.Null); ok {
		response = nil
	}

	enveloped := nhttp.IsEnvelopeStyle(ctx, cfg.GetStyle())
	if enveloped {
		code := core.NewErrorCode(200)
		message := "OK"
		if sc := cfg.GetEnvelope().SuccessCode; len(sc) > 0 {
			if c, err := core.ParseErrorCode(sc); err != nil {
				logs.Ctx(ctx).Warnw("failed to parse the user setting success code, will use \"200\" indeed.", "code", sc, "error", err)
			} else {
				code = c
			}
		}
		if msg := cfg.GetEnvelope().SuccessMessage; len(msg) > 0 {
			message = msg
		}

		totalCount := int32(0)
		nextPageToken := ""
		if p, ok := response.(pagination.Paginator); ok {
			totalCount = p.GetTotalCount()
			nextPageToken = p.GetNextPageToken()
		}

		response = &nhttp.EnvelopedResponse{
			Error: &core.Error{
				Code:    code,
				Message: message,
			},
			TotalCount:    totalCount,
			NextPageToken: nextPageToken,
			Data:          response,
		}
	}

	if response == nil {
		return nil
	}

	if p, ok := response.(pagination.Paginator); ok && !enveloped {
		total := p.GetTotalCount()
		if total > 0 {
			w.Header().Set("X-Total-Count", strconv.Itoa(int(total)))
		}

		next := p.GetNextPageToken()
		if len(next) > 0 {
			path, _ := ctx.Value(requestPathKey).(string)
			if len(path) == 0 {
				path = "/?pageToken=" + next
			} else {
				url, _ := core.ParseUrl(path)
				url.Query.Add("pageToken", next)
				path = url.Format()
			}
			w.Header().Set("Link", fmt.Sprintf("<%s>; rel=\"next\"", path))
		}
	}

	return nhttp.NewResponseJsonWriter(response).WriteHttpResponse(ctx, w)
}

// Helper functions

func isNilResponse(response interface{}) bool {
	if response == nil {
		return true
	}

	value := reflect.ValueOf(response)
	switch value.Kind() {
	case reflect.Chan, reflect.Func, reflect.Interface, reflect.Map, reflect.Pointer, reflect.Slice:
		return value.IsNil()
	default:
		return false
	}
}

type contextKey uint8

const requestPathKey contextKey = iota

func headersToContext(cfg *nhttp.Config) httptransport.RequestFunc {
	return func(ctx context.Context, r *http.Request) context.Context {
		if locale := firstNonEmpty(r.Header.Get("X-Locale"), r.Header.Get("Locale"), r.Header.Get("Accept-Language")); len(locale) > 0 {
			ctx = localemw.WithLocale(ctx, locale)
		}

		if sessionID := firstNonEmpty(r.Header.Get("X-Session-Key"), r.Header.Get("Session-Key"), r.Header.Get("Session_Key"), bearerToken(r.Header.Get("Authorization"))); len(sessionID) > 0 {
			ctx = session.WithToken(ctx, sessionID)
		}

		ctx = contexts.WithClientIP(ctx, cfg.ClientIP(r))
		ctx = context.WithValue(ctx, requestPathKey, r.URL.RequestURI())

		return ctx
	}
}

func queryToContext(ctx context.Context, r *http.Request) context.Context {
	check := func(values []string) bool {
		for _, value := range values {
			if value == "true" {
				return true
			}
		}
		return false
	}

	for key, values := range r.URL.Query() {
		switch key {
		case "envelope":
			if check(values) {
				ctx = context.WithValue(ctx, "envelope", true)
			}
		case "locale":
			if locale := firstNonEmpty(values...); len(locale) > 0 {
				ctx = localemw.WithLocale(ctx, locale)
			}
		case "session_key":
			if sessionID := firstNonEmpty(values...); len(sessionID) > 0 {
				ctx = session.WithToken(ctx, sessionID)
			}
		}
	}

	return ctx
}

func firstNonEmpty(values ...string) string {
	for _, value := range values {
		value = strings.TrimSpace(value)
		if len(value) > 0 {
			return value
		}
	}
	return ""
}

func bearerToken(value string) string {
	const prefix = "Bearer "

	value = strings.TrimSpace(value)
	if len(value) < len(prefix) || !strings.EqualFold(value[:len(prefix)], prefix) {
		return ""
	}
	return strings.TrimSpace(value[len(prefix):])
}

func unmarshalPathParam(params map[string]string, value interface{}, keys ...string) error {
	for _, key := range keys {
		if val, _ := params[key]; len(val) > 0 {
			return core.UnmarshalParam(val, value)
		}
	}
	return core.NewNotFoundError("path param not found, tried keys: %v", keys)
}

func unmarshalQueryParam(params *core.Url_Query, value interface{}, keys ...string) error {
	for _, k := range keys {
		if params.Has(k) {
			return params.Unmarshal(k, value)
		}
	}
	return core.NewNotFoundError("query param not found ,tried keys: %v", keys)
}
